//! Per-Run state types shared by [`engine`](super::engine) and the [`app`]
//! command surface.

use serde::{Deserialize, Serialize};

/// Opaque Run identifier (UUIDv4, generated by the storage layer on insert).
pub type RunId = uuid::Uuid;

/// Lifecycle states a Run can occupy.
///
/// The set mirrors the Docker edition's documented states and is treated as
/// the single source of truth across storage, engine, and Tauri command
/// surface.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RunStatus {
    Queued,
    Running,
    WaitingApproval,
    BudgetExtensionPending,
    Interrupted,
    Failed,
    Cancelled,
    Completed,
}

impl RunStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            RunStatus::Queued => "queued",
            RunStatus::Running => "running",
            RunStatus::WaitingApproval => "waiting_approval",
            RunStatus::BudgetExtensionPending => "budget_extension_pending",
            RunStatus::Interrupted => "interrupted",
            RunStatus::Failed => "failed",
            RunStatus::Cancelled => "cancelled",
            RunStatus::Completed => "completed",
        }
    }

    pub fn is_terminal(&self) -> bool {
        matches!(
            self,
            RunStatus::Completed
                | RunStatus::Failed
                | RunStatus::Cancelled
                | RunStatus::Interrupted
        )
    }
}

/// Public-facing Run snapshot used by the Tauri command surface and the
/// SSE-equivalent event stream.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RunView {
    pub id: RunId,
    pub conversation_id: uuid::Uuid,
    pub mode: String,
    pub status: RunStatus,
    pub model_id: String,
    pub step_count: u32,
    pub tool_call_count: u32,
    pub started_at: chrono::DateTime<chrono::Utc>,
    pub updated_at: chrono::DateTime<chrono::Utc>,
    pub summary: String,
    pub budget: serde_json::Value,
    /// Terminal error text when the Run failed (provider error, context
    /// overflow, …). `None` for a Run that did not fail. Surfaced so the UI can
    /// explain why a Run stopped instead of leaving a silent spinner.
    #[serde(default)]
    pub error: Option<String>,
}

pub type RunState = RunView;
